1	"use client";
2	
3	import { useState } from "react";
4	import { Send } from "lucide-react";
5	import { Button, buttonClass } from "@/components/ui/Button";
6	import { Input, Select, Textarea } from "@/components/ui/Field";
7	
8	export type SupportSite = {
9	  id: string;
10	  name: string;
11	  /** The real public address, computed server-side. Not a guess. */
12	  address: string;
13	  published: boolean;
14	};
15	
16	/* The message body is capped below the endpoint's own 5000-character ceiling
17	   so that the site context prepended in `compose` can never be what pushes a
18	   perfectly reasonable message over the limit. */
19	const MESSAGE_MAX = 4000;
20	
21	type Status = "idle" | "sending" | "sent";
22	
23	function compose(input: {
24	  accountEmail: string;
25	  site: SupportSite | undefined;
26	  message: string;
27	}): string {
28	  const { accountEmail, site, message } = input;
29	  const lines = [`Kodely account: ${accountEmail}`];
30	
31	  if (site) {
32	    lines.push(`Site: ${site.name}`);
33	    lines.push(`Address: ${site.address}${site.published ? "" : " (not published yet)"}`);
34	    lines.push(`Builder: ${window.location.origin}/projects/${site.id}`);
35	  } else {
36	    lines.push("Site: not about one specific site");
37	  }
38	
39	  return `${lines.join("\n")}\n\n---\n\n${message}`;
40	}
41	
42	export function ContactPanel({
43	  accountEmail,
44	  accountName,
45	  sites,
46	  contactEmail,
47	}: {
48	  accountEmail: string;
49	  accountName: string;
50	  sites: SupportSite[];
51	  contactEmail: string;
52	}) {
53	  const [name, setName] = useState(accountName);
54	  const [email, setEmail] = useState(accountEmail);
55	  const [siteId, setSiteId] = useState("");
56	  const [message, setMessage] = useState("");
57	  const [status, setStatus] = useState<Status>("idle");
58	  const [error, setError] = useState<string | null>(null);
59	
60	  function submit(event: React.FormEvent) {
61	    event.preventDefault();
62	    if (status === "sending") return;
63	    setStatus("sending");
64	    setError(null);
65	
66	    const body = JSON.stringify({
67	      name: name.trim(),
68	      email: email.trim(),
69	      message: compose({
70	        accountEmail,
71	        site: sites.find((s) => s.id === siteId),
72	        message: message.trim(),
73	      }),
74	    });
75	
76	    void (async () => {
77	      try {
78	        const res = await fetch("/api/contact", {
79	          method: "POST",
80	          headers: { "Content-Type": "application/json" },
81	          body,
82	        });
83	        // Every failure branch of /api/contact returns a sentence written for a
84	        // person — not configured, rate limited, rejected, SMTP down — so the
85	        // honest thing is to show it rather than replace it with our own guess.
86	        const data = (await res.json().catch(() => ({}))) as { error?: string };
87	        if (!res.ok) {
88	          setError(data.error ?? "That didn't send, and we don't know why.");
89	          setStatus("idle");
90	          return;
91	        }
92	        setStatus("sent");
93	        setMessage("");
94	      } catch {
95	        setError(`Couldn't reach Kodely at all. Email ${contactEmail} directly and it will land.`);
96	        setStatus("idle");
97	      }
98	    })();
99	  }
100	
101	  if (status === "sent") {
102	    return (
103	      <div role="status" className="rounded-lg border border-ok/30 bg-ok-tint p-5">
104	        <p className="k-h2 text-ink">Sent</p>
105	        <p className="mt-2 text-sm leading-relaxed text-ink-2">
106	          It is in the inbox a person reads. The reply goes to{" "}
107	          <span className="font-medium text-ink">{email}</span> as an ordinary email — there is
108	          nothing to come back to this page for, and nothing here will change when we answer.
109	        </p>
110	        <button
111	          type="button"
112	          onClick={() => setStatus("idle")}
113	          className={buttonClass({ variant: "secondary", size: "sm", className: "mt-4" })}
114	        >
115	          Send another
116	        </button>
117	      </div>
118	    );
119	  }
120	
121	  const sending = status === "sending";
122	  const remaining = MESSAGE_MAX - message.length;
123	
124	  return (
125	    <form onSubmit={submit} className="flex flex-col gap-4">
126	      <div className="grid gap-4 sm:grid-cols-2">
127	        <Input
128	          label="Your name"
129	          value={name}
130	          onChange={(e) => setName(e.target.value)}
131	          autoComplete="name"
132	          required
133	          maxLength={120}
134	          disabled={sending}
135	        />
136	        <Input
137	          label="Reply to"
138	          type="email"
139	          value={email}
140	          onChange={(e) => setEmail(e.target.value)}
141	          autoComplete="email"
142	          required
143	          disabled={sending}
144	          hint="Prefilled from your account. Change it if you want the reply somewhere else."
145	        />
146	      </div>
147	
148	      <Select
149	        label="Which site is this about?"
150	        value={siteId}
151	        onChange={(e) => setSiteId(e.target.value)}
152	        disabled={sending || sites.length === 0}
153	        hint={
154	          sites.length === 0
155	            ? "You have no sites yet, so there is nothing to attach."
156	            : "We send the site's name and address along with your message, so nobody has to ask you for them."
157	        }
158	      >
159	        <option value="">Not about one specific site</option>
160	        {sites.map((site) => (
161	          <option key={site.id} value={site.id}>
162	            {site.name}
163	            {site.published ? "" : " (draft)"}
164	          </option>
165	        ))}
166	      </Select>
167	
168	      <Textarea
169	        label="What's going on?"
170	        value={message}
171	        onChange={(e) => setMessage(e.target.value)}
172	        rows={7}
173	        required
174	        maxLength={MESSAGE_MAX}
175	        disabled={sending}
176	        hint={
177	          remaining < 400
178	            ? `${remaining} characters left.`
179	            : "What you expected, what happened instead, and anything you already tried."
180	        }
181	      />
182	
183	      {error != null && (
184	        <p
185	          role="alert"
186	          className="rounded-md border border-danger/30 bg-danger-tint px-3 py-2.5 text-sm leading-relaxed text-danger"
187	        >
188	          {error}
189	        </p>
190	      )}
191	
192	      <div className="flex flex-wrap items-center gap-3">
193	        <Button
194	          type="submit"
195	          variant="primary"
196	          loading={sending}
197	          icon={<Send className="size-4" aria-hidden />}
198	        >
199	          {sending ? "Sending" : "Send message"}
200	        </Button>
201	        <p className="text-xs text-ink-3">
202	          Or email{" "}
203	          <a
204	            href={`mailto:${contactEmail}`}
205	            className="k-focus rounded-sm underline underline-offset-2"
206	          >
207	            {contactEmail}
208	          </a>{" "}
209	          — same inbox.
210	        </p>
211	      </div>
212	    </form>
213	  );
214	}
