1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { db } from "@/lib/db";
4	import { getAdminUser } from "@/lib/auth";
5	import { ADMIN_ACTIONS, recordAdminAction } from "@/lib/admin-audit";
6	import { EVENTS } from "@/lib/events";
7	import {
8	  Empty,
9	  Panel,
10	  StatTile,
11	  TableFrame,
12	  Th,
13	  formatDateTime,
14	  truncate,
15	} from "../users/ui";
16	import {
17	  Bar,
18	  Caution,
19	  RatingPill,
20	  REASONS,
21	  buttonClass,
22	  controlClass,
23	  isReasonId,
24	  reasonLabel,
25	} from "./ui";
26	
27	export const dynamic = "force-dynamic";
28	
29	// The individual side of the satisfaction percentage on /admin. That number is
30	// the temperature; this page is the thermometer reading you can act on — one
31	// row per thumbs-up/down, with the reason the customer picked.
32	//
33	// Everything here is derived from `build.rated` events (lib/events.ts, written
34	// by app/api/feedback/route.ts). Nothing on this page writes to the stream.
35	
36	/**
37	 * How many ratings are pulled into memory. Ratings are low-volume by nature
38	 * (a fraction of builds get rated at all), and the aggregates below — the
39	 * reason breakdown and the repair cross-tab — have to be computed over the
40	 * SAME set that the table shows, or the panels would quietly disagree with
41	 * each other. One bounded read, no query in a loop.
42	 */
43	const WINDOW = 500;
44	
45	/** Rows rendered after filtering. The window above is the honest denominator. */
46	const ROW_LIMIT = 200;
47	
48	type Rated = {
49	  id: string;
50	  createdAt: Date;
51	  userId: string | null;
52	  rating: "up" | "down" | null;
53	  reason: string | null;
54	  model: string | null;
55	  buildId: string | null;
56	  projectId: string | null;
57	  /** null when the event predates the prop, not zero — the two are different facts. */
58	  repairAttempts: number | null;
59	};
60	
61	function str(v: unknown): string | null {
62	  return typeof v === "string" && v.length > 0 ? v : null;
63	}
64	
65	function num(v: unknown): number | null {
66	  return typeof v === "number" && Number.isFinite(v) ? v : null;
67	}
68	
69	/**
70	 * Props are Json and therefore untrusted shape-wise: an event written before a
71	 * prop existed simply lacks it. Every field is read defensively so one odd row
72	 * cannot blank the page.
73	 */
74	function parseRated(row: { id: string; createdAt: Date; userId: string | null; props: unknown }): Rated {
75	  const p =
76	    row.props !== null && typeof row.props === "object" && !Array.isArray(row.props)
77	      ? (row.props as Record<string, unknown>)
78	      : {};
79	  const rating = str(p.rating);
80	  return {
81	    id: row.id,
82	    createdAt: row.createdAt,
83	    userId: row.userId,
84	    rating: rating === "up" || rating === "down" ? rating : null,
85	    reason: str(p.reason),
86	    model: str(p.model),
87	    buildId: str(p.buildId),
88	    projectId: str(p.projectId),
89	    repairAttempts: num(p.repairAttempts),
90	  };
91	}
92	
93	function first(v: string | string[] | undefined): string {
94	  if (Array.isArray(v)) return v[0] ?? "";
95	  return v ?? "";
96	}
97	
98	function href(params: { rating: string; reason: string }): string {
99	  const sp = new URLSearchParams();
100	  if (params.rating) sp.set("rating", params.rating);
101	  if (params.reason) sp.set("reason", params.reason);
102	  const qs = sp.toString();
103	  return qs ? `/admin/feedback?${qs}` : "/admin/feedback";
104	}
105	
106	function pct(part: number, whole: number): number | null {
107	  return whole === 0 ? null : Math.round((part / whole) * 1000) / 10;
108	}
109	
110	/** One row of the repair cross-tab. */
111	type Bucket = { label: string; hint: string; up: number; down: number };
112	
113	export default async function AdminFeedbackPage({
114	  searchParams,
115	}: {
116	  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
117	}) {
118	  // Defense in depth — app/admin/layout.tsx is the primary gate, but a layout
119	  // is not an authorization boundary on its own. 404 rather than redirect, so
120	  // a non-admin who reaches this path learns nothing from it.
121	  const admin = await getAdminUser();
122	  if (!admin) notFound();
123	
124	  const sp = await searchParams;
125	  const ratingRaw = first(sp.rating);
126	  const rating = ratingRaw === "up" || ratingRaw === "down" ? ratingRaw : "";
127	  const reasonRaw = first(sp.reason);
128	  const reason = reasonRaw === "none" || isReasonId(reasonRaw) ? reasonRaw : "";
129	
130	  // Recorded BEFORE the ratings are read, and awaited — see recordAdminAction
131	  // in lib/admin-audit.ts. This page shows what named customers said about
132	  // their builds, so looking at it is an access to customer data.
133	  //
134	  // The filters go in meta for the same reason /admin/audit records its own:
135	  // "who went looking for what" is the part of a read worth keeping. Both are
136	  // validated against closed sets above, so a hand-typed query string cannot
137	  // push anything into the log that is not one of these words — and neither
138	  // carries a customer identifier.
139	  await recordAdminAction(admin, ADMIN_ACTIONS.feedbackViewed, {
140	    meta: { filteredByRating: rating || null, filteredByReason: reason || null },
141	  });
142	
143	  const [total, rows] = await Promise.all([
144	    db.event.count({ where: { name: EVENTS.buildRated } }),
145	    db.event.findMany({
146	      where: { name: EVENTS.buildRated },
147	      // Served straight off the @@index([name, createdAt]) on Event.
148	      orderBy: { createdAt: "desc" },
149	      take: WINDOW,
150	      select: { id: true, createdAt: true, userId: true, props: true },
151	    }),
152	  ]);
153	
154	  const ratings = rows.map(parseRated);
155	
156	  // Two id→label lookups for the whole window, not one query per row.
157	  const userIds = [...new Set(ratings.map((r) => r.userId).filter((v): v is string => v !== null))];
158	  const projectIds = [
159	    ...new Set(ratings.map((r) => r.projectId).filter((v): v is string => v !== null)),
160	  ];
161	
162	  const [users, projects] = await Promise.all([
163	    userIds.length
164	      ? db.user.findMany({ where: { id: { in: userIds } }, select: { id: true, email: true } })
165	      : Promise.resolve([]),
166	    projectIds.length
167	      ? db.project.findMany({ where: { id: { in: projectIds } }, select: { id: true, name: true } })
168	      : Promise.resolve([]),
169	  ]);
170	
171	  const emailById = new Map(users.map((u) => [u.id, u.email]));
172	  const projectById = new Map(projects.map((p) => [p.id, p.name]));
173	
174	  // ── Aggregates, over the whole window rather than the filtered view ──────
175	  // Filtering the breakdown by the filter it is meant to explain would make
176	  // every bar 100%.
177	  const up = ratings.filter((r) => r.rating === "up").length;
178	  const down = ratings.filter((r) => r.rating === "down").length;
179	  const rated = up + down;
180	
181	  // Counted over THUMBS-DOWN only, because `down` is the denominator the panel
182	  // shows percentages against. Today's UI (app/projects/[id]/BuildRating.tsx)
183	  // only offers the reason list after a thumbs-down, but the API accepts
184	  // `reason` on either rating — so scoping here is what makes
185	  // `withReason + noReason === down` true by construction rather than by luck,
186	  // and keeps a stray up-with-a-reason from printing a percentage over 100.
187	  const downRatings = ratings.filter((r) => r.rating === "down");
188	  const reasonCounts = REASONS.map((r) => ({
189	    ...r,
190	    count: downRatings.filter((x) => x.reason === r.id).length,
191	  }));
192	  const noReason = downRatings.filter((r) => r.reason === null).length;
193	  const maxReason = Math.max(0, ...reasonCounts.map((r) => r.count), noReason);
194	  const withReason = reasonCounts.reduce((a, b) => a + b.count, 0);
195	
196	  // ── The question this page exists to answer ──────────────────────────────
197	  // A thumbs-down on a build that needed a repair pass and a thumbs-down on a
198	  // build that compiled first try are two different bugs. The first says the
199	  // repair loop ships something that limps (reliability). The second says the
200	  // output was fine mechanically and still wasn't what they asked for
201	  // (quality). Averaging them together hides both.
202	  const clean = ratings.filter((r) => r.repairAttempts === 0);
203	  const repaired = ratings.filter((r) => r.repairAttempts !== null && r.repairAttempts > 0);
204	  const unknownRepairs = ratings.filter((r) => r.repairAttempts === null);
205	
206	  const buckets: Bucket[] = [
207	    {
208	      label: "Compiled first try",
209	      hint: "repairAttempts = 0",
210	      up: clean.filter((r) => r.rating === "up").length,
211	      down: clean.filter((r) => r.rating === "down").length,
212	    },
213	    {
214	      label: "Needed a repair pass",
215	      hint: "repairAttempts ≥ 1",
216	      up: repaired.filter((r) => r.rating === "up").length,
217	      down: repaired.filter((r) => r.rating === "down").length,
218	    },
219	  ];
220	  if (unknownRepairs.length > 0) {
221	    buckets.push({
222	      label: "Not recorded",
223	      hint: "event has no repairAttempts prop",
224	      up: unknownRepairs.filter((r) => r.rating === "up").length,
225	      down: unknownRepairs.filter((r) => r.rating === "down").length,
226	    });
227	  }
228	
229	  const cleanRated = buckets[0].up + buckets[0].down;
230	  const repairedRated = buckets[1].up + buckets[1].down;
231	  const cleanDownRate = pct(buckets[0].down, cleanRated);
232	  const repairedDownRate = pct(buckets[1].down, repairedRated);
233	  const gap =
234	    cleanDownRate !== null && repairedDownRate !== null ? repairedDownRate - cleanDownRate : null;
235	
236	  // n is small for a long while after launch. Say so rather than letting three
237	  // ratings read as a finding.
238	  const enoughToRead = cleanRated >= 10 && repairedRated >= 10;
239	
240	  // ── The filtered view ────────────────────────────────────────────────────
241	  const filtered = ratings.filter((r) => {
242	    if (rating && r.rating !== rating) return false;
243	    if (reason === "none") return r.reason === null;
244	    if (reason && r.reason !== reason) return false;
245	    return true;
246	  });
247	  const visible = filtered.slice(0, ROW_LIMIT);
248	  const filtering = rating !== "" || reason !== "";
249	
250	  return (
251	    <div className="mx-auto max-w-6xl px-6 py-10">
252	      <div className="mb-8">
253	        <Link
254	          href="/admin"
255	          className="rounded text-xs text-black/50 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:text-white/50 dark:focus-visible:ring-white/40"
256	        >
257	          ← kodely admin
258	        </Link>
259	        <div className="mt-1 text-lg font-semibold tracking-tight">Support inbox</div>
260	        <p className="text-sm text-black/60 dark:text-white/60">
261	          Every individual build rating, newest first. /admin gives the satisfaction percentage;
262	          this is what is actually behind it.{" "}
263	          <Link
264	            href="/admin/feedback/notes"
265	            className="rounded underline underline-offset-4 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
266	          >
267	            Operator notes →
268	          </Link>
269	        </p>
270	      </div>
271	
272	      {total === 0 ? (
273	        <Caution title="Nothing recorded yet — do not read this as good news">
274	          <p>
275	            There are zero <code className="font-mono text-xs">build.rated</code> events in the
276	            database. Ratings only started being collected very recently, and the event stream holds
277	            nothing from before that shipped.
278	          </p>
279	          <p className="mt-2">
280	            An empty inbox here is indistinguishable from a page where everybody is happy. It is
281	            neither: it is a page with no data. Every count, percentage and bar below is computed
282	            over an empty set.
283	          </p>
284	        </Caution>
285	      ) : null}
286	
287	      <div className="mb-8 grid grid-cols-2 gap-4 sm:grid-cols-4">
288	        <StatTile
289	          label="Ratings in window"
290	          value={rated}
291	          hint={
292	            total > ratings.length
293	              ? `most recent ${ratings.length} of ${total}`
294	              : total === 0
295	                ? "nothing recorded yet"
296	                : "the whole stream"
297	          }
298	        />
299	        <StatTile
