222	/**
223	 * Sent once, right after an account is created. Idempotent on the user row
224	 * itself: an account is created exactly once, and the age guard below means a
225	 * stray second call an hour later does nothing even after a restart clears the
226	 * in-process claim.
227	 */
228	const WELCOME_MAX_AGE_MS = 60 * 60 * 1000;
229	
230	export async function sendWelcome(userId: string): Promise<SendResult> {
231	  return send("welcome", userId, async () => {
232	    const user = await db.user.findUnique({
233	      where: { id: userId },
234	      select: { email: true, name: true, createdAt: true },
235	    });
236	    if (!user?.email) return null;
237	    if (Date.now() - user.createdAt.getTime() > WELCOME_MAX_AGE_MS) return null;
238	    return { to: user.email, email: welcomeEmail({ name: user.name }) };
239	  });
240	}
