244	/**
245	 * The balance warning. `crossingLedgerId` is the ledger row that took this
246	 * user below the line — it is the dedupe key, so one crossing produces one
247	 * email no matter how many times this is called. See scanLowCredits().
248	 */
249	export async function sendLowCredits(userId: string, crossingLedgerId: string): Promise<SendResult> {
250	  return send("low_credits", crossingLedgerId, async () => {
251	    const user = await db.user.findUnique({ where: { id: userId }, select: { email: true } });
252	    if (!user?.email) return null;
253	
254	    // Re-read the balance at send time: they may have topped up between the
255	    // scan and now, and "you're running low" to someone who just paid is the
256	    // worst possible version of this email.
257	    const [balance, avg, chargedBuilds] = await Promise.all([
258	      getBalance(userId),
259	      averageBuildCredits(userId),
260	      // Whether `avg` is their own measured number or the global fallback —
261	      // the same condition averageBuildCredits() uses to decide. The email
262	      // claims one or the other, so it has to know which.
263	      db.build.count({
264	        where: { project: { userId }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
265	      }),
266	    ]);
267	    const state = creditState(balance, avg);
268	    if (!state.needsWarning) return null;
269	
270	    return {
271	      to: user.email,
272	      email: lowCreditsEmail({
273	        balance: state.balance,
274	        avgBuildCredits: state.avgBuildCredits,
275	        canTopUp: billingEnabled(),
276	        measured: chargedBuilds > 0,
277	        state,
278	      }),
279	    };
280	  });
281	}
