285	export async function sendBuildFailed(buildId: string): Promise<SendResult> {
286	  return send("build_failed", buildId, async () => {
287	    const build = await db.build.findUnique({
288	      where: { id: buildId },
289	      select: {
290	        status: true,
291	        error: true,
292	        creditsCharged: true,
293	        project: { select: { id: true, name: true, user: { select: { email: true } } } },
294	      },
295	    });
296	    if (!build || build.status !== "FAILED") return null;
297	    if (!build.project.user.email) return null;
298	
299	    // The email states plainly that they were not charged. Only say it if the
300	    // ledger agrees: creditsCharged is 0 on the build AND no ledger row points
301	    // at it. app/api/generate/route.ts never charges a failed build, so this
302	    // should always hold — but this is a factual claim about someone's money,
303	    // and it gets verified rather than assumed.
304	    if (build.creditsCharged !== 0) return null;
305	    const charged = await db.creditLedger.count({ where: { buildId } });
306	    if (charged > 0) return null;
307	
308	    return {
309	      to: build.project.user.email,
310	      email: buildFailedEmail({ projectName: build.project.name, projectId: build.project.id }),
311	    };
312	  });
313	}
