348	// ── Fire-and-forget wrappers ──────────────────────────────────────────────
349	//
350	// These are the ones to call from request paths. They return void, never a
351	// promise, so there is no await to forget and no rejection to handle: a
352	// notification physically cannot delay or fail the request that triggered it.
353	//
354	// Nothing calls them yet — the routes that would (signup, generate, publish)
355	// are owned by other modules and this module may not edit them. Each is a
356	// single line at the call site:
357	//
358	//   app/api/auth/signup/route.ts        notifyWelcome(user.id)
359	//   app/api/auth/google/callback        notifyWelcome(user.id)   [new users only]
360	//   app/api/generate/route.ts           notifyBuildFailed(build.id)
361	//   app/api/projects/[id]/publish       notifySitePublished(id)
362	//
363	// Wiring notifyWelcome means the cron no longer should: set
364	// KODELY_NOTIFY_WELCOME_CRON=0 in the same change. The other two are safe to
365	// wire with the cron still running — the same claim key is used on both paths
366	// within a process, and the cron's own scan only looks at closed slots.
367	
368	function fireAndForget(work: Promise<SendResult>): void {
369	  void work.catch((err) => console.error("[notifications] unreachable:", err));
370	}
371	
372	export function notifyWelcome(userId: string): void {
373	  fireAndForget(sendWelcome(userId));
374	}
375	
376	export function notifyLowCredits(userId: string, crossingLedgerId: string): void {
377	  fireAndForget(sendLowCredits(userId, crossingLedgerId));
378	}
379	
380	export function notifyBuildFailed(buildId: string): void {
381	  fireAndForget(sendBuildFailed(buildId));
382	}
383	
384	export function notifySitePublished(projectId: string): void {
385	  fireAndForget(sendSitePublished(projectId));
386	}
