1	import { SIGNUP_GRANT, estimateCredits, MICROS_PER_CREDIT } from "@/lib/credits";
2	import { creditState, runwaySentence, type CreditState } from "./credit-state";
3	
4	// Transactional email bodies for Kodely.
5	//
6	// Rules this file exists to enforce:
7	//
8	// 1. PLAIN TEXT IS THE REAL EMAIL. Every message is composed as a list of
9	//    blocks and rendered to text first; the HTML alternative is generated from
10	//    the SAME blocks, so the two can never drift apart or say different things.
11	// 2. NO REMOTE ANYTHING. No images, no tracking pixel, no web fonts, no
12	//    external CSS. Every style is inlined, and the mail makes zero network
13	//    requests when opened — so opening it tells us nothing and leaks nothing.
14	// 3. NOTHING SENSITIVE IN THE BODY. No credentials, tokens, session ids,
15	//    prompt text, generated file contents, or build error strings. Build
16	//    errors in particular can quote the user's own source; they belong in the
17	//    app, behind auth, not in an inbox that may be shared or forwarded.
18	// 4. GENUINELY TRANSACTIONAL. Every one of these is triggered by the sender's
19	//    own account state (their signup, their balance, their build, their
20	//    publish). There is no consent record and no unsubscribe mechanism in this
21	//    product, so nothing here may be promotional or re-engagement-shaped.
22	
23	export type EmailKind = "welcome" | "low_credits" | "build_failed" | "site_published";
24	
25	export type Email = { subject: string; text: string; html: string };
26	
27	export function appUrl(): string {
28	  // Same variable and default as app/api/billing/checkout/route.ts.
29	  return (process.env.APP_URL ?? "https://kodely.me").replace(/\/+$/, "");
30	}
31	
32	// ── Block rendering ───────────────────────────────────────────────────────
33	
34	type Block =
35	  | { kind: "p"; text: string }
36	  | { kind: "ul"; items: string[] }
37	  | { kind: "cta"; label: string; href: string }
38	  | { kind: "link"; label: string; href: string }
39	  | { kind: "note"; text: string };
40	
41	const p = (text: string): Block => ({ kind: "p", text });
42	const ul = (items: string[]): Block => ({ kind: "ul", items });
43	const cta = (label: string, href: string): Block => ({ kind: "cta", label, href });
44	const link = (label: string, href: string): Block => ({ kind: "link", label, href });
45	const note = (text: string): Block => ({ kind: "note", text });
46	
47	function escapeHtml(value: string): string {
48	  return value
49	    .replace(/&/g, "&amp;")
50	    .replace(/</g, "&lt;")
51	    .replace(/>/g, "&gt;")
52	    .replace(/"/g, "&quot;")
53	    .replace(/'/g, "&#39;");
54	}
55	
56	/**
57	 * Blocks only ever carry plain text, and every value is escaped on the way
58	 * into the HTML, so a project name of `<script>` is inert — user-supplied
59	 * strings reach these templates (project names) and must never become markup.
60	 */
61	function safeText(value: string, max = 200): string {
62	  return value.replace(/[\u0000-\u001F\u007F]+/g, " ").replace(/\s+/g, " ").trim().slice(0, max);
63	}
64	
65	/** Only ever used on URLs we build ourselves; a bad one is dropped, not sent. */
66	function safeUrl(value: string): string {
67	  return /^https?:\/\/[^\s"'<>]+$/.test(value) ? value : appUrl();
68	}
69	
70	function wrap(text: string, width = 72): string {
71	  const out: string[] = [];
72	  let line = "";
73	  for (const word of text.split(/\s+/)) {
74	    if (line === "") line = word;
75	    else if (line.length + 1 + word.length <= width) line += ` ${word}`;
76	    else {
77	      out.push(line);
78	      line = word;
79	    }
80	  }
81	  if (line !== "") out.push(line);
82	  return out.join("\n");
83	}
84	
85	const FOOTER =
86	  "You're receiving this because it concerns your own Kodely account. " +
87	  "We only send email about your account — never marketing.";
88	
89	function renderText(blocks: Block[]): string {
90	  const parts: string[] = [];
91	  for (const b of blocks) {
92	    if (b.kind === "p") parts.push(wrap(b.text));
93	    else if (b.kind === "note") parts.push(wrap(b.text));
94	    else if (b.kind === "ul") parts.push(b.items.map((i) => wrap(`- ${i}`, 70)).join("\n"));
95	    else parts.push(`${b.label}: ${b.href}`);
96	  }
97	  parts.push("--");
98	  parts.push(wrap(FOOTER));
99	  return `${parts.join("\n\n")}\n`;
100	}
101	
102	// Inline styles only — every mail client strips <style> blocks somewhere.
103	const S = {
104	  body: "margin:0;padding:24px;background:#f6f7f8;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#111111;",
105	  card: "max-width:520px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;padding:28px;",
106	  p: "margin:0 0 16px 0;font-size:15px;line-height:1.6;color:#111111;",
107	  li: "margin:0 0 8px 0;font-size:15px;line-height:1.6;color:#111111;",
108	  ul: "margin:0 0 16px 0;padding-left:20px;",
109	  cta: "display:inline-block;margin:4px 0 20px 0;padding:10px 18px;background:#111111;color:#ffffff;text-decoration:none;border-radius:8px;font-size:15px;font-weight:600;",
110	  link: "margin:0 0 16px 0;font-size:15px;line-height:1.6;",
111	  note: "margin:0 0 16px 0;font-size:14px;line-height:1.6;color:#4b5563;",
112	  footer: "margin:24px 0 0 0;padding-top:16px;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.5;color:#6b7280;",
113	  wordmark: "margin:0 0 20px 0;font-size:14px;font-weight:600;letter-spacing:-0.01em;color:#111111;",
114	};
115	
116	function renderHtml(subject: string, blocks: Block[]): string {
117	  const body = blocks
118	    .map((b) => {
119	      if (b.kind === "p") return `<p style="${S.p}">${escapeHtml(b.text)}</p>`;
120	      if (b.kind === "note") return `<p style="${S.note}">${escapeHtml(b.text)}</p>`;
121	      if (b.kind === "ul")
122	        return `<ul style="${S.ul}">${b.items
123	          .map((i) => `<li style="${S.li}">${escapeHtml(i)}</li>`)
124	          .join("")}</ul>`;
125	      if (b.kind === "cta")
126	        return `<p style="margin:0;"><a href="${escapeHtml(b.href)}" style="${S.cta}">${escapeHtml(
127	          b.label,
128	        )}</a></p>`;
129	      return `<p style="${S.link}"><a href="${escapeHtml(b.href)}" style="color:#111111;">${escapeHtml(
130	        b.href,
131	      )}</a></p>`;
132	    })
133	    .join("\n      ");
134	
135	  return `<!doctype html>
136	<html lang="en">
137	  <head>
138	    <meta charset="utf-8">
139	    <meta name="viewport" content="width=device-width,initial-scale=1">
140	    <title>${escapeHtml(subject)}</title>
141	  </head>
142	  <body style="${S.body}">
143	    <div style="${S.card}">
144	      <p style="${S.wordmark}">kodely</p>
145	      ${body}
146	      <p style="${S.footer}">${escapeHtml(FOOTER)}</p>
147	    </div>
148	  </body>
149	</html>
150	`;
151	}
152	
153	function compose(subject: string, blocks: Block[]): Email {
154	  return { subject, text: renderText(blocks), html: renderHtml(subject, blocks) };
155	}
156	
157	/** "you" when we have no name — never a raw email address in the greeting. */
158	function greetingName(name: string | null | undefined): string {
159	  const clean = safeText(name ?? "", 40);
160	  return clean === "" ? "" : clean;
161	}
