/* Prose styling for blog/SEO content (BlogPost.bodyHtml) — hand-rolled
   Small, named, reused everywhere in the portal and builder. Each one exists
   because expressing it as a Tailwind class chain at every call site is how
   the old portal drifted out of alignment with itself.
   ══════════════════════════════════════════════════════════════════════════ */

/* One focus treatment for the whole product. Always visible, never removed —
   a ring that only shows on :focus-visible still has to exist. */
.k-focus:focus-visible {
  outline: 2px solid var(--brand-ring);
  outline-offset: 2px;
}

/* Type scale. Display sizes get negative tracking (optical correction — at
   32px+ the default spacing reads loose); the label size gets positive
   tracking and uppercase, which is the only place caps are used. */
.k-display {
  font-size: clamp(1.75rem, 1.2rem + 1.6vw, 2.35rem);
  line-height: 1.1;
  letter-spacing: -0.028em;
  font-weight: 600;
  text-wrap: balance;
}
.k-h1 {
  font-size: 1.5rem;
  line-height: 1.2;
  letter-spacing: -0.02em;
  font-weight: 600;
}
.k-h2 {
  font-size: 1.0625rem;
  line-height: 1.35;
  letter-spacing: -0.011em;
  font-weight: 600;
}
.k-label {
  font-size: 0.6875rem;
  line-height: 1;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--text-3);
}
/* Anywhere digits stack in a column — usage, credits, invoices, versions. */
.k-num {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

/* Any wide child (table, code, diagram) scrolls inside its own box so the
   page body never scrolls sideways. */
.k-scroll-x {
  overflow-x: auto;
  overscroll-behavior-x: contain;
}

/* A 1px brand-gradient hairline around a panel, done with a padding box so it
   works on any background without a second opaque layer to keep in sync. */
.k-gradient-border {
  background:
    linear-gradient(var(--surface), var(--surface)) padding-box,
    var(--brand-gradient) border-box;
  border: 1px solid transparent;
}

/* ── AI progress: the three states a step can be in ──
   Reused by the build overlay, the chat progress list and the preview
  transform: none;
  transition:
    filter var(--t-3) var(--ease-io),
    transform var(--t-3) var(--ease-io);
}

/* Chat message entrance — one shared animation so an assistant reply and a
   progress row arrive the same way. */
@keyframes k-msg-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.k-msg-in {
  animation: k-msg-in 0.28s var(--ease) both;
}

/* Ambient brand wash for hero panels inside the product (dashboard welcome,
   create-website prompt). Softer than the marketing .aura and NOT fixed —
   it belongs to its panel and scrolls with it. */
.k-wash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  border-radius: inherit;
}
.k-wash::before,
.k-wash::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  filter: blur(72px);
}
.k-wash::before {
  width: 46%;
  aspect-ratio: 1;
  left: -6%;
  top: -42%;
  background: radial-gradient(closest-side, var(--glow), transparent);
}
.k-wash::after {
  width: 40%;
  aspect-ratio: 1;
  right: -4%;
  bottom: -50%;
  background: radial-gradient(closest-side, var(--glow-2), transparent);
}

/* Sidebar collapse. The width lives on the shell as a custom property so the
   sidebar, the mobile drawer and the main column all animate off one value
