import { Badge, type Tone } from "@/components/ui/Badge";
import { SUPPORT_STATUS_INFO, isSupportStatus } from "@/lib/support";

// Presentational bits and form-state shapes shared by the support pages.
//
// Not a route — only page/layout/route filenames are routable — so it is safe
// beside them. The form-state types live here rather than next to the Server
// Actions because a "use server" file may only export async functions, which
// is the same reason app/admin/feedback/ui.tsx holds NOTE_MAX.

/**
 * Status colour, and the second channel that goes with it.
 *
 * `dot` is set on the two live states and NOT on the finished one, which is
 * the rule in the design system: colour alone is not a status channel, and
 * "resolved" is the one state that is not still moving. Nothing here is
 * `brand` — status colour is never the brand colour.
 */
const STATUS_TONE: Record<string, { tone: Tone; dot: boolean }> = {
  OPEN: { tone: "info", dot: true },
  ANSWERED: { tone: "ok", dot: true },
  RESOLVED: { tone: "neutral", dot: false },
};

export function TicketStatus({ status }: { status: string }) {
  // A status written before this vocabulary existed still renders as itself
  // rather than as a blank pill.
  if (!isSupportStatus(status)) return <Badge tone="neutral">{status}</Badge>;
  const { tone, dot } = STATUS_TONE[status];
  return (
    <Badge tone={tone} dot={dot}>
      {SUPPORT_STATUS_INFO[status].customerLabel}
    </Badge>
  );
}

/**
 * There is a reply on this thread the customer has not opened.
 *
 * Deliberately its own pill rather than a third status: "we replied" and "you
 * have not read it" are different facts, and collapsing them would mean the
 * badge changed when they clicked, which reads as the status having changed.
 */
export function UnreadPill() {
  return (
    <Badge tone="brand" dot pulse>
      New reply
    </Badge>
  );
}

export type TicketFormState = { error: string | null };

export const TICKET_FORM_INITIAL: TicketFormState = { error: null };

"use server";

import { redirect } from "next/navigation";
import { refresh } from "next/cache";
import { db } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { checkSupportMessageRateLimit, checkSupportTicketRateLimit } from "@/lib/rate-limit";
import {
  BODY_MAX,
  BODY_MIN,
  DEFAULT_SUPPORT_CATEGORY,
  SUBJECT_MAX,
  appendMessage,
  isSupportCategory,
} from "@/lib/support";
import type { TicketFormState } from "./ui";

// The customer's three writes. Everything else on /support reads.
//
// Server Functions are reachable by direct POST, not only through the forms
// that render them, so every one of these resolves the session ITSELF and
// scopes every query by that user's id — app/(portal)/layout.tsx redirecting
// signed-out visitors is not an authorization boundary for a POST that never
// passes through it. Same rule, and the same reason, as
// app/admin/feedback/actions.ts.

function field(data: FormData, name: string): string {
  const raw = data.get(name);
  return typeof raw === "string" ? raw.trim() : "";
}

/**
 * Collapse the control characters a paste can carry, keep newlines.
 *
 * Bodies are rendered with `whitespace-pre-wrap` and never as HTML, on either
 * side, so this is about legibility rather than safety — but a NUL or a stray
 * escape sequence in an operator's terminal-shaped world is worth removing at
 * the boundary rather than at each place it is read.
 */
function cleanBody(value: string): string {
  return value.replace(/\r\n/g, "\n").replace(/[�-  -]/g, "");
}

const RATE_LIMITED_TICKET =
  "That is a lot of tickets in a short time. Add what is left to an existing thread, " +
  "or try again a little later — nothing you have already sent is lost.";

export async function createTicket(
  _prev: TicketFormState,
  formData: FormData,
): Promise<TicketFormState> {
  const user = await getCurrentUser();
  if (!user) return { error: "You are signed out. Sign in again and your message will send." };

  const subject = field(formData, "subject");
  const body = cleanBody(field(formData, "body"));
  const rawCategory = field(formData, "category");
  const rawProjectId = field(formData, "projectId");

  if (subject.length < 3) return { error: "Give it a subject — a few words is plenty." };
  if (subject.length > SUBJECT_MAX) {
    return { error: `That subject is ${subject.length} characters. Keep it under ${SUBJECT_MAX}.` };
  }
  if (body.length < BODY_MIN) return { error: "Tell us what is going on, even roughly." };
  if (body.length > BODY_MAX) {
    return {
      error: `That message is ${body.length} characters and the limit is ${BODY_MAX}. Send the essentials and we will ask for the rest.`,
    };
  }

  // An unrecognised category is not an error the customer should see — the
  // select is a closed list, so anything else came from a hand-made POST.
  // Falling back is safer than rejecting: the ticket still reaches a human.
  const category = isSupportCategory(rawCategory) ? rawCategory : DEFAULT_SUPPORT_CATEGORY;

  // Ownership is checked in the SAME query that fetches the project. A site
  // that is not theirs must be indistinguishable from one that does not
  // exist — never "look it up, then compare userId".
  let projectId: string | null = null;
  if (rawProjectId !== "") {
    const project = await db.project.findFirst({
      where: { id: rawProjectId, userId: user.id },
      select: { id: true },
    });
    if (!project) return { error: "That site is not on your account any more. Pick another." };
    projectId = project.id;
  }

  const limit = await checkSupportTicketRateLimit(user.id);
  if (!limit.allowed) return { error: RATE_LIMITED_TICKET };

  const ticketId = await db.$transaction(async (tx) => {
    const ticket = await tx.supportTicket.create({
      data: { userId: user.id, subject, category, projectId },
      select: { id: true },
    });
    // The first message goes through the same writer as every later one, so
    // a new ticket cannot end up with different bookkeeping from a reply.
    await appendMessage(tx, { ticketId: ticket.id, author: "CUSTOMER", body });
    return ticket.id;
  });

  // Straight into the thread. redirect() signals by throwing, so it must stay
  // outside any try/catch — and it means the success branch never returns a
  // state, which is why TicketFormState carries only an error.
  redirect(`/support/${ticketId}`);
}

export async function sendReply(
  _prev: TicketFormState,
  formData: FormData,
): Promise<TicketFormState> {
  const user = await getCurrentUser();
  if (!user) return { error: "You are signed out. Sign in again and your reply will send." };

  const ticketId = field(formData, "ticketId");
  const body = cleanBody(field(formData, "body"));

  if (body.length < BODY_MIN) return { error: "There is nothing in that reply." };
  if (body.length > BODY_MAX) {
    return { error: `That reply is ${body.length} characters and the limit is ${BODY_MAX}.` };
  }

  const ticket = await db.supportTicket.findFirst({
    where: { id: ticketId, userId: user.id },
    select: { id: true },
  });
  if (!ticket) return { error: "That ticket is not on your account." };

  const limit = await checkSupportMessageRateLimit(user.id);
  if (!limit.allowed) {
    return { error: "That is a lot of replies in an hour. Give it a moment and try again." };
  }

  // Replying to a resolved ticket reopens it — appendMessage sets OPEN from
  // the author, so reopening is not a separate action anyone has to remember.
  await db.$transaction((tx) => appendMessage(tx, { ticketId: ticket.id, author: "CUSTOMER", body }));

  refresh();
  return { error: null };
}

export async function resolveTicket(
  _prev: TicketFormState,
  formData: FormData,
): Promise<TicketFormState> {
  const user = await getCurrentUser();
  if (!user) return { error: "You are signed out." };

  const ticketId = field(formData, "ticketId");

  // updateMany, not update: it takes the ownership filter in the WHERE, so
  // there is no window between checking and writing.
  const { count } = await db.supportTicket.updateMany({
    where: { id: ticketId, userId: user.id },
    data: { status: "RESOLVED" },
  });
  if (count === 0) return { error: "That ticket is not on your account." };

  refresh();
  return { error: null };
}

