import { SUPPORT_STATUS_INFO, isSupportStatus } from "@/lib/support";

// Presentational bits for the ticket queue, in the panel's own idiom —
// monochrome, hairline borders, colour only where it carries a meaning. The
// base primitives (Panel, StatTile, TableFrame, Th, Empty, formatDateTime,
// truncate) and the shared control styling come from the users and feedback
// pages rather than being re-declared, so the support queue reads as the same
// panel and not a look-alike.
//
// NOTE this deliberately does NOT import components/ui. The customer's
// /support is built from the product design system; the admin panel is a
// different, plainer system on purpose, and mixing them is how the two start
// to drift into a third thing.

/**
 * Status, as an operator reads it.
 *
 * Different words from the customer's badge for the same three values —
 * "Needs a reply" is what it means from this side, "Waiting on us" is what it
 * means from theirs — and both come out of the same record in lib/support.ts,
 * so they cannot end up describing different states.
 */
export function StatusPill({ status }: { status: string }) {
  if (!isSupportStatus(status)) {
    return <span className="text-black/40 dark:text-white/40">{status}</span>;
  }
  const label = SUPPORT_STATUS_INFO[status].staffLabel;
  if (status === "OPEN") {
    return (
      <span className="whitespace-nowrap font-medium text-amber-600 dark:text-amber-500">
        {label}
      </span>
    );
  }
  if (status === "ANSWERED") {
    return (
      <span className="whitespace-nowrap font-medium text-emerald-600 dark:text-emerald-400">
        {label}
      </span>
    );
  }
  return <span className="whitespace-nowrap text-black/50 dark:text-white/50">{label}</span>;
}

/** Nobody on our side has opened what this customer last wrote. */
export function UnseenPill() {
  return (
    <span className="rounded-full border border-amber-500/40 bg-amber-500/10 px-1.5 py-0.5 text-[0.6875rem] font-medium whitespace-nowrap text-amber-700 dark:text-amber-500">
      unread
    </span>
  );
}

/**
 * A reply is published to the customer the instant it is written, so the cap
 * is not about storage — it is about what an operator is likely to paste. The
 * customer's own composer allows the same 5000 characters (BODY_MAX in
 * lib/support.ts) and this stays in step with it deliberately: a thread where
 * one side can say more than the other is a thread that gets truncated
 * mid-explanation.
 *
 * Lives here rather than beside the Server Action because a "use server" file
 * may only export async functions — same reason as NOTE_MAX in
 * app/admin/feedback/ui.tsx.
 */
export type AdminTicketFormState = { error: string | null; ok: boolean };

export const ADMIN_TICKET_FORM_INITIAL: AdminTicketFormState = { error: null, ok: false };

"use server";

import { refresh } from "next/cache";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import { ADMIN_ACTIONS, ADMIN_TARGET_TYPES, adminActionRow } from "@/lib/admin-audit";
import { notifySupportReply } from "@/lib/notifications/send";
import { BODY_MAX, BODY_MIN, appendMessage, isSupportStatus } from "@/lib/support";
import type { AdminTicketFormState } from "./ui";

// The two mutations the ticket queue performs. Everything else on these pages
// reads.
//
// Server Functions are reachable by direct POST, not only through this UI, so
// the admin check happens HERE and not merely on the page that renders the
// form — app/admin/layout.tsx is the primary gate but a layout is not an
// authorization boundary. Same rule as app/admin/feedback/actions.ts.

function field(data: FormData, name: string): string {
  const raw = data.get(name);
  return typeof raw === "string" ? raw.trim() : "";
}

/** Normalise line endings, drop control characters, keep newlines and tabs. */
function cleanBody(value: string): string {
  let out = "";
  for (const ch of value.replace(/\r\n/g, "\n")) {
    const code = ch.codePointAt(0) ?? 0;
    if ((code >= 32 && code !== 127) || code === 10 || code === 9) out += ch;
  }
  return out;
}

/**
 * Reply to a customer.
 *
 * THIS IS THE ONE WRITE IN THE ADMIN PANEL WHOSE OUTPUT IS PUBLISHED. What is
 * typed here appears in that customer's own thread on /support the moment the
 * transaction commits, and an email goes out telling them to read it. It is
 * the opposite of a SupportNote, which is written about a customer and never
 * shown to one; nothing copies between the two, and this is not the place to
 * put anything you would only write because they cannot see it.
 */
export async function replyToTicket(
  _prev: AdminTicketFormState,
  formData: FormData,
): Promise<AdminTicketFormState> {
  const admin = await getAdminUser();
  if (!admin) return { error: "You are not signed in as an admin.", ok: false };

  const ticketId = field(formData, "ticketId");
  const body = cleanBody(field(formData, "body"));

  if (body.length < BODY_MIN) return { error: "A reply needs something in it.", ok: false };
  if (body.length > BODY_MAX) {
    return {
      error: `That is ${body.length} characters — the customer's composer stops at ${BODY_MAX}, and so does this. Split it, or point at the app.`,
      ok: false,
    };
  }

  // Verify the target rather than letting the foreign key throw: a 500 on a
  // stale tab is a worse answer than a sentence.
  const ticket = await db.supportTicket.findUnique({
    where: { id: ticketId },
    select: { id: true, status: true },
  });
  if (!ticket) return { error: "That ticket no longer exists.", ok: false };

  // The reply and its audit row go in together or not at all. adminActionRow
  // rather than recordAdminAction exists for exactly this: a message the
  // customer can read must not be able to exist without the row saying who
  // sent it, and there must be no log row for a reply that rolled back.
  //
  // meta holds IDS AND A LENGTH, never the reply text. The body is already
  // disclosable to the customer and returned in their data export; copying it
  // into the audit log would double the number of places it has to be found
  // and redacted, for no gain — the id joins straight back to the message.
  const messageId = await db.$transaction(async (tx) => {
    const message = await appendMessage(tx, {
      ticketId: ticket.id,
      author: "STAFF",
      // From the session, never from the form. Attribution nobody can spoof is
      // the whole point of recording it.
      staffEmail: admin.email,
      body,
    });
    await tx.adminAuditLog.create({
      data: adminActionRow(admin, ADMIN_ACTIONS.ticketReplied, {
        targetType: ADMIN_TARGET_TYPES.supportTicket,
        targetId: ticket.id,
        meta: { messageId: message.id, chars: body.length, statusBefore: ticket.status },
      }),
    });
    return message.id;
  });

  // OUTSIDE the transaction, and fire-and-forget: a dead SMTP server must
  // never roll back or delay a reply the customer can already read on their
  // thread. The email is the notification; the thread is the mechanism.
  notifySupportReply(messageId);

  refresh();
  return { error: null, ok: true };
}

/**
 * Change a ticket's status by hand.
 *
 * In practice this means RESOLVED — OPEN and ANSWERED are set by the act of
 * somebody writing, so setting them here is only ever undoing a mistake. The
 * full vocabulary is offered anyway, because a status you can reach but not
 * leave is a trap.
 */
export async function changeTicketStatus(
  _prev: AdminTicketFormState,
  formData: FormData,
): Promise<AdminTicketFormState> {
  const admin = await getAdminUser();
  if (!admin) return { error: "You are not signed in as an admin.", ok: false };

  const ticketId = field(formData, "ticketId");
  const status = field(formData, "status");
  // Closed set, checked with hasOwnProperty inside isSupportStatus. A form
  // field is untrusted input however few options the <select> renders.
  if (!isSupportStatus(status)) return { error: "That is not a status.", ok: false };

  const ticket = await db.supportTicket.findUnique({
    where: { id: ticketId },
    select: { id: true, status: true },
  });
  if (!ticket) return { error: "That ticket no longer exists.", ok: false };
  if (ticket.status === status) return { error: null, ok: true };

  // SupportTicket keeps only the CURRENT status, so the previous value exists
  // nowhere else once this commits — which is why it goes in meta, and why the
  // row is written in the same transaction as the change it records.
  await db.$transaction([
    db.supportTicket.update({ where: { id: ticket.id }, data: { status } }),
    db.adminAuditLog.create({
      data: adminActionRow(admin, ADMIN_ACTIONS.ticketStatusChanged, {
        targetType: ADMIN_TARGET_TYPES.supportTicket,
        targetId: ticket.id,
        meta: { from: ticket.status, to: status },
      }),
    }),
  ]);

  refresh();
  return { error: null, ok: true };
}

"use client";

import { useActionState } from "react";
import { BODY_MAX, SUPPORT_STATUSES, SUPPORT_STATUS_INFO } from "@/lib/support";
import { buttonClass, controlClass } from "../feedback/ui";
import { changeTicketStatus, replyToTicket } from "./actions";
import { ADMIN_TICKET_FORM_INITIAL } from "./ui";

// The two write surfaces on a thread. Client components only so the operator
// gets a pending state and an inline error instead of a full page reload with
// a half-written reply lost — both `<form action>`s still post without
// JavaScript, and React clears the textarea itself once the action resolves.

export function ReplyBox({ ticketId, customerEmail }: { ticketId: string; customerEmail: string }) {
  const [state, formAction, pending] = useActionState(replyToTicket, ADMIN_TICKET_FORM_INITIAL);

  return (
    <form action={formAction}>
      <input type="hidden" name="ticketId" value={ticketId} />

      <label htmlFor="reply-body" className="block text-sm font-medium">
        Reply to {customerEmail}
      </label>

      {/* Not a placeholder and not a tooltip: this has to be readable while
          the operator is typing, which is the moment it matters. */}
      <p id="reply-guidance" className="mt-1 text-xs text-black/60 dark:text-white/60">
        <strong>This is published to the customer on send.</strong> It appears in their thread on
        /support immediately and they are emailed to say so. It is not a support note — anything
        you would only write because they cannot see it belongs in{" "}
        <span className="font-mono text-[0.6875rem]">/admin/feedback/notes</span> instead.
      </p>

      <textarea
        id="reply-body"
        name="body"
        rows={6}
        required
        maxLength={BODY_MAX}
        aria-describedby="reply-guidance reply-status"
        placeholder="You weren't charged for that build — failed builds never are. The 40 credits on the 21st were the successful rebuild an hour later; here's the line in your history…"
        className="mt-2 w-full resize-y rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-black/40 focus-visible:ring-2 focus-visible:ring-black/40 dark:border-white/10 dark:placeholder:text-white/40 dark:focus-visible:ring-white/40"
      />

      <div className="mt-2 flex flex-wrap items-center gap-3">
        <button type="submit" className={buttonClass} disabled={pending}>
          {pending ? "Sending…" : "Send reply"}
        </button>
        <span className="text-xs text-black/50 dark:text-white/50">
          Up to {BODY_MAX} characters. Replies cannot be edited or unsent.
        </span>
      </div>

      {/* One live region for both outcomes, so a screen reader hears the result
          of the submit it just made without the focus moving anywhere. */}
      <p
        id="reply-status"
        role="status"
        aria-live="polite"
        className={`mt-2 text-sm ${
          state.error ? "text-red-600 dark:text-red-400" : "text-emerald-600 dark:text-emerald-400"
        }`}
      >
        {state.error ? state.error : state.ok ? "Sent. The customer can see it now." : ""}
      </p>
    </form>
  );
}

export function StatusForm({ ticketId, status }: { ticketId: string; status: string }) {
  const [state, formAction, pending] = useActionState(
    changeTicketStatus,
    ADMIN_TICKET_FORM_INITIAL,
  );

  return (
    <form action={formAction} className="flex flex-wrap items-center gap-2">
      <input type="hidden" name="ticketId" value={ticketId} />
      <label htmlFor="status-select" className="text-sm text-black/60 dark:text-white/60">
        Status
      </label>
      <select id="status-select" name="status" defaultValue={status} className={controlClass}>
        {SUPPORT_STATUSES.map((s) => (
          <option key={s} value={s}>
            {SUPPORT_STATUS_INFO[s].staffLabel}
          </option>
        ))}
      </select>
      <button type="submit" className={buttonClass} disabled={pending}>
        {pending ? "Saving…" : "Set"}
      </button>
      <span
        role="status"
        aria-live="polite"
        className="text-xs text-black/50 dark:text-white/50"
      >
        {state.error ?? ""}
      </span>
      <span className="basis-full text-xs text-black/50 dark:text-white/50">
        Replying already sets this — a reply marks it answered, and anything the customer sends
        puts it back to needing one. Set it by hand only to close a thread or undo a mis-set one.
      </span>
    </form>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { getAdminUser } from "@/lib/auth";
import { ADMIN_ACTIONS, recordAdminAction } from "@/lib/admin-audit";
import {
  SUPPORT_STATUSES,
  SUPPORT_STATUS_INFO,
  categoryShort,
  countTicketsByStatus,
  isSupportStatus,
  isUnseenByStaff,
  listStaffTickets,
} from "@/lib/support";
import { Empty, Panel, StatTile, TableFrame, Th, formatDateTime, truncate } from "../users/ui";
import { buttonClass, controlClass } from "../feedback/ui";
import { StatusPill, UnseenPill } from "./ui";

export const dynamic = "force-dynamic";

// The ticket queue.
//
// WHY THIS IS ITS OWN SECTION AND NOT PART OF /admin/feedback. The two look
// adjacent — both are "customer signal" — but they are different objects with
// different obligations. /admin/feedback is derived entirely from `build.rated`
// events, states in its own subtitle that nothing on it writes to the stream,
// and is a page you READ to find a trend. This is a WORK QUEUE with a state
// machine, a per-thread page, and the one write in the panel whose output is
// published straight to a customer. Folding a queue into an analytics page
// would mean an operator's "is anything waiting?" and "what is the thumbs-down
// rate?" share a filter bar, and the first question is the urgent one.
//
// They link to each other in both directions instead, since "this customer
// rated a build badly" and "this customer wrote to us" are worth reading
// together.

/** Rows per page. Tickets are low volume; this is a guard, not pagination UX. */
const PAGE = 50;

function first(v: string | string[] | undefined): string {
  if (Array.isArray(v)) return v[0] ?? "";
  return v ?? "";
}

function href(params: { status: string; page: number }): string {
  const sp = new URLSearchParams();
  if (params.status) sp.set("status", params.status);
  if (params.page > 0) sp.set("page", String(params.page + 1));
  const qs = sp.toString();
  return qs ? `/admin/support?${qs}` : "/admin/support";
}

export default async function AdminSupportPage({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  // Defense in depth — app/admin/layout.tsx is the primary gate, but a layout
  // is not an authorization boundary on its own. 404 rather than redirect, so
  // a non-admin who reaches this path learns nothing from it.
  const admin = await getAdminUser();
  if (!admin) notFound();

  const sp = await searchParams;
  // Validated against the closed vocabulary with hasOwnProperty (see
  // isSupportStatus). Anything else is simply "no filter".
  const statusRaw = first(sp.status);
  const status = isSupportStatus(statusRaw) ? statusRaw : undefined;

  const pageRaw = Number.parseInt(first(sp.page), 10);
  const page = Number.isFinite(pageRaw) && pageRaw > 1 ? pageRaw - 1 : 0;

  // Recorded BEFORE anything is read, and awaited — see recordAdminAction in
  // lib/admin-audit.ts. This page lists customer emails next to the subjects
  // they wrote, so looking at it is an access to customer data.
  //
  // The filter goes in meta for the same reason /admin/audit records its own:
  // "who went looking for what" is the part of a read worth keeping. It is
  // validated against a closed set above, so nothing a hand-typed query string
  // carries can reach the log, and it holds no customer identifier.
  await recordAdminAction(admin, ADMIN_ACTIONS.ticketQueueViewed, {
    meta: { filteredByStatus: status ?? null, page: page + 1 },
  });

  const [counts, { rows, total }] = await Promise.all([
    countTicketsByStatus(),
    listStaffTickets({ status, skip: page * PAGE, take: PAGE }),
  ]);

  const open = counts.get("OPEN") ?? 0;
  const answered = counts.get("ANSWERED") ?? 0;
  const resolved = counts.get("RESOLVED") ?? 0;
  const allTickets = open + answered + resolved;

  // Counted over the page in hand, and labelled as such. "Unread" needs the
  // read marks, which are per row — claiming a number across the whole table
  // would mean a second query that says something different from the table
  // underneath it.
  const unseenHere = rows.filter(isUnseenByStaff).length;

  const shownFrom = total === 0 ? 0 : page * PAGE + 1;
  const shownTo = page * PAGE + rows.length;

  return (
    <div className="mx-auto max-w-6xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin"
          className="rounded text-xs text-black/50 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:text-white/50 dark:focus-visible:ring-white/40"
        >
          ← kodely admin
        </Link>
        <div className="mt-1 text-lg font-semibold tracking-tight">Support tickets</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          What customers actually wrote to us, and the thread they are waiting on.{" "}
          <Link
            href="/admin/feedback"
            className="rounded underline underline-offset-4 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
          >
            Build ratings →
          </Link>{" "}
          <Link
            href="/admin/feedback/notes"
            className="rounded underline underline-offset-4 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
          >
            Operator notes →
          </Link>
        </p>
      </div>

      <div className="mb-8 grid grid-cols-2 gap-4 sm:grid-cols-4">
        <StatTile
          label="Needs a reply"
          value={<span className={open > 0 ? "text-amber-600 dark:text-amber-500" : ""}>{open}</span>}
          tone={open > 0 ? "warn" : undefined}
          hint={open === 0 ? "nothing waiting" : "the customer wrote last"}
        />
        <StatTile label="Answered" value={answered} hint="waiting on the customer" />
        <StatTile label="Resolved" value={resolved} hint="closed by either side" />
        <StatTile
          label="Unread on this page"
          value={unseenHere}
          hint={`of ${rows.length} shown — nobody has opened these`}
        />
      </div>

      <form method="get" action="/admin/support" className="mb-6 flex flex-wrap items-center gap-2">
        <label htmlFor="status-filter" className="text-sm text-black/60 dark:text-white/60">
          Status
        </label>
        <select id="status-filter" name="status" defaultValue={status ?? ""} className={controlClass}>
          <option value="">All statuses</option>
          {SUPPORT_STATUSES.map((s) => (
            <option key={s} value={s}>
              {SUPPORT_STATUS_INFO[s].staffLabel}
            </option>
          ))}
        </select>
        <button type="submit" className={buttonClass}>
          Filter
        </button>
        {status ? (
          <Link
            href="/admin/support"
            className="rounded text-sm text-black/50 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:text-white/50 dark:focus-visible:ring-white/40"
          >
            Clear
          </Link>
        ) : null}
      </form>

      <Panel
        title="Tickets"
        subtitle={
          <>
            Newest activity first.{" "}
            {total === 0
              ? "Nothing matches."
              : `Showing ${shownFrom}–${shownTo} of ${total}${status ? ` with status ${SUPPORT_STATUS_INFO[status].staffLabel.toLowerCase()}` : ""}.`}{" "}
            Subjects are the customer&apos;s own words; the message bodies are on the thread, not
            here.
          </>
        }
      >
        {rows.length === 0 ? (
          <Empty>
            {allTickets === 0 ? (
              <>
                No tickets have been opened at all. Unlike the rating inbox, this is the whole
                table rather than a window — an empty queue here really does mean nobody has
                written.
              </>
            ) : status ? (
              <>No tickets with that status.</>
            ) : (
              <>Nothing on this page. Try the first one.</>
            )}
          </Empty>
        ) : (
          <TableFrame>
            <thead>
              <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
                <Th>Last activity</Th>
                <Th>Status</Th>
                <Th>Subject</Th>
                <Th>About</Th>
                <Th>Customer</Th>
                <Th>Site</Th>
                <Th align="right">Msgs</Th>
              </tr>
            </thead>
            <tbody className="divide-y divide-black/10 dark:divide-white/10">
              {rows.map((t) => (
                <tr key={t.id}>
                  <td className="whitespace-nowrap px-4 py-2 tabular-nums text-black/70 dark:text-white/70">
                    {formatDateTime(t.lastMessageAt)}
                  </td>
                  <td className="px-4 py-2">
                    <span className="flex flex-wrap items-center gap-1.5">
                      <StatusPill status={t.status} />
                      {isUnseenByStaff(t) && <UnseenPill />}
                    </span>
                  </td>
                  <td className="max-w-[20rem] px-4 py-2">
                    <Link
                      href={`/admin/support/${t.id}`}
                      className="rounded underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
                      title={t.subject}
                    >
                      {truncate(t.subject, 60)}
                    </Link>
                  </td>
                  <td className="px-4 py-2 text-black/70 dark:text-white/70">
                    {categoryShort(t.category)}
                  </td>
                  <td className="max-w-[14rem] px-4 py-2">
                    {t.user ? (
                      <Link
                        href={`/admin/users/${t.user.id}`}
                        className="rounded underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
                        title={`${t.user.email} — open their account`}
                      >
                        {truncate(t.user.email, 28)}
                      </Link>
                    ) : (
                      <span className="text-black/30 dark:text-white/30">deleted account</span>
                    )}
                  </td>
                  <td className="max-w-[12rem] px-4 py-2 text-black/70 dark:text-white/70">
                    {t.project ? (
                      truncate(t.project.name, 24)
                    ) : (
                      <span className="text-black/30 dark:text-white/30">—</span>
                    )}
                  </td>
                  <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                    {t.messageCount}
                  </td>
                </tr>
              ))}
            </tbody>
          </TableFrame>
        )}

        {(page > 0 || shownTo < total) && (
          <div className="mt-4 flex items-center justify-between text-sm">
            {page > 0 ? (
              <Link
                href={href({ status: status ?? "", page: page - 1 })}
                className="rounded underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
              >
                ← Newer
              </Link>
            ) : (
              <span />
            )}
            {shownTo < total ? (
              <Link
                href={href({ status: status ?? "", page: page + 1 })}
                className="rounded underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
              >
                Older →
              </Link>
            ) : (
              <span />
            )}
          </div>
        )}
      </Panel>

      <p className="mt-6 text-xs text-black/50 dark:text-white/50">
        &ldquo;Unread&rdquo; means nobody has opened the thread since the customer last wrote on
        it — it is the read mark, not the status. A ticket can be answered and unread (they replied
        after your answer) or waiting and read (somebody looked and did not write back). Opening a
        thread clears it, and every open is recorded in the audit log.
      </p>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { getAdminUser } from "@/lib/auth";
import { ADMIN_ACTIONS, ADMIN_TARGET_TYPES, recordAdminAction } from "@/lib/admin-audit";
import {
  categoryLabel,
  getStaffTicket,
  markStaffRead,
  type TicketMessage,
} from "@/lib/support";
import { Empty, Panel, formatDateTime } from "../../users/ui";
import { Caution } from "../../feedback/ui";
import { ReplyBox, StatusForm } from "../TicketActions";
import { StatusPill } from "../ui";

export const dynamic = "force-dynamic";

// One support thread, and the two things an operator does with it.

function Message({ message, unseen }: { message: TicketMessage; unseen: boolean }) {
  const staff = message.author === "STAFF";
  return (
    <li
      className={[
        "rounded-xl border p-4",
        staff
          ? "border-black/10 bg-black/[0.02] dark:border-white/10 dark:bg-white/[0.02]"
          : "border-black/10 dark:border-white/10",
        unseen ? "ring-1 ring-amber-500/40" : "",
      ]
        .filter(Boolean)
        .join(" ")}
    >
      <div className="flex flex-wrap items-baseline justify-between gap-x-3 text-xs text-black/50 dark:text-white/50">
        <span className="font-medium text-black/70 dark:text-white/70">
          {/* The staff address is shown HERE and never to the customer: this is
              the record of who answered, and it is the panel's job to keep it.
              Their thread says "Kodely support". */}
          {staff ? (message.staffEmail ?? "Kodely support") : "Customer"}
        </span>
        <span className="tabular-nums">{formatDateTime(message.createdAt)}</span>
      </div>
      {/* Customer-written text on one side and operator-written on the other,
          rendered as text and never as HTML, with whitespace preserved. Shown
          in full: both are length-capped at the point they were written, and
          truncating the thing a person wrote on purpose defeats the page. */}
      <p className="mt-2 text-sm whitespace-pre-wrap break-words">{message.body}</p>
    </li>
  );
}

export default async function AdminSupportThreadPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  // Defense in depth — see app/admin/support/page.tsx. The layout gate is the
  // primary one, but a layout must not be the sole authorization boundary.
  const admin = await getAdminUser();
  if (!admin) notFound();

  const { id } = await params;

  // Recorded BEFORE the thread is even looked up, and awaited. This is the
  // most concentrated view of one customer's own words in the panel, and
  // recording first means a probe at an id that turns out not to exist still
  // leaves a row — an operator typing ids into the URL bar is exactly the
  // access this log is for.
  //
  // The id is the TARGET rather than meta, which is what makes "everything
  // anyone did to this thread" a real query: targetType/targetId is the column
  // AdminAuditLog indexes.
  await recordAdminAction(admin, ADMIN_ACTIONS.ticketViewed, {
    targetType: ADMIN_TARGET_TYPES.supportTicket,
    targetId: id,
  });

  // Marked read before the fetch, keeping the previous mark, so the messages
  // nobody had seen are still highlighted on the render that clears them.
  const read = await markStaffRead(id);
  if (!read) notFound();

  const thread = await getStaffTicket(id);
  if (!thread) notFound();

  const { ticket, messages } = thread;

  const unseenIds = new Set(
    messages
      .filter(
        (m) =>
          m.author === "CUSTOMER" && (read.previous === null || m.createdAt > read.previous),
      )
      .map((m) => m.id),
  );

  return (
    <div className="mx-auto max-w-4xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin/support"
          className="rounded text-xs text-black/50 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:text-white/50 dark:focus-visible:ring-white/40"
        >
          ← Support tickets
        </Link>
        <div className="mt-1 text-lg font-semibold tracking-tight">{ticket.subject}</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          <StatusPill status={ticket.status} /> · {categoryLabel(ticket.category)} · opened{" "}
          <span className="tabular-nums">{formatDateTime(ticket.createdAt)}</span>
        </p>
        <p className="mt-1 text-sm text-black/60 dark:text-white/60">
          {ticket.user ? (
            <>
              <Link
                href={`/admin/users/${ticket.user.id}`}
                className="rounded underline underline-offset-4 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
              >
                {ticket.user.email}
              </Link>
              {" · "}
              <Link
                href={`/admin/feedback/notes/${ticket.user.id}`}
                className="rounded underline underline-offset-4 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
              >
                operator notes →
              </Link>
            </>
          ) : (
            <span className="text-black/40 dark:text-white/40">deleted account</span>
          )}
          {ticket.project ? (
            <>
              {" · "}
              <Link
                href={`/admin/sites/${ticket.project.id}`}
                className="rounded underline underline-offset-4 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
              >
                {ticket.project.name} →
              </Link>
            </>
          ) : (
            " · no site attached"
          )}
        </p>
        <p className="mt-1 font-mono text-xs text-black/40 dark:text-white/40">{ticket.id}</p>
      </div>

      <Caution title="A reply here is published to the customer">
        <p>
          Anything sent below appears in this person&apos;s own thread on{" "}
          <code className="font-mono text-xs">/support</code> the moment it commits, and they are
          emailed to say so. That is the difference between this and an operator note: a note is
          written <em>about</em> a customer and is never rendered to them, a reply is written{" "}
          <em>to</em> one and always is. Nothing copies between the two tables in either direction.
        </p>
        <p className="mt-2">
          Both are disclosable if this person asks for their data, so neither is a private channel
          — but only one of them is on their screen.
        </p>
      </Caution>

      <div className="mb-8">
        <Panel
          title="Thread"
          subtitle={`${messages.length} message(s), oldest first. Amber ring = written since anyone on our side last opened this.`}
        >
          {messages.length === 0 ? (
            <Empty>
              This ticket has no messages, which should be impossible — a ticket is created with
              its first one in the same transaction. Worth looking at.
            </Empty>
          ) : (
            <ol className="space-y-3">
              {messages.map((m) => (
                <Message key={m.id} message={m} unseen={unseenIds.has(m.id)} />
              ))}
            </ol>
          )}
        </Panel>
      </div>

      <div className="mb-8">
        <Panel
          title="Reply"
          subtitle="Sending marks the ticket answered. If they write back it goes to needing a reply again, by itself."
        >
          <ReplyBox
            ticketId={ticket.id}
            customerEmail={ticket.user?.email ?? "a deleted account"}
          />
        </Panel>
      </div>

      <Panel
        title="Status"
        subtitle="Three values, and only one of them is usually set by hand."
      >
        <StatusForm ticketId={ticket.id} status={ticket.status} />
      </Panel>
    </div>
  );
}

